import bpy
for o in list(bpy.data.objects):
    bpy.data.objects.remove(o, do_unlink=True)
bpy.ops.curve.primitive_bezier_curve_add(location=(0, 0, 0))
bpy.ops.object.mode_set(mode='EDIT')
bpy.ops.curve.select_all(action='SELECT')
act = bpy.context.view_layer.objects.active
for old, new in {'Sphere': 'Planet', 'Cylinder': 'Cylinder'}.items():
    o = bpy.data.objects.get(old)
    if o is not None and o != act:
        o.name = new
if act is not None:
    act.name = 'BezierCurve'
o = bpy.data.objects.get('Planet')
if o is not None and not o.select_get():
    o.location = (-6, 4, 0)
o = bpy.data.objects.get('Cylinder')
if o is not None and not o.select_get():
    o.location = (4, -3, 0)
bpy.context.scene.frame_set(5)
